CREATE TABLE IF NOT EXISTS collections (id TEXT NOT NULL, tenant_id TEXT NOT NULL, name TEXT NOT NULL, state TEXT NOT NULL, schema_version BIGINT NOT NULL, version BIGINT NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, created_by TEXT NOT NULL, updated_by TEXT NOT NULL, deleted_at TIMESTAMPTZ, PRIMARY KEY (tenant_id, id), UNIQUE (tenant_id, name));
CREATE TABLE IF NOT EXISTS wal_records (sequence BIGSERIAL PRIMARY KEY, tenant_id TEXT NOT NULL, collection_id TEXT NOT NULL, document_id TEXT NOT NULL, operation TEXT NOT NULL, version BIGINT NOT NULL, payload JSONB, checksum TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS segments (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, collection_id TEXT NOT NULL, generation BIGINT NOT NULL, state TEXT NOT NULL, checksum TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS outbox (id UUID PRIMARY KEY, aggregate_id TEXT NOT NULL, event_type TEXT NOT NULL, payload JSONB NOT NULL, status TEXT NOT NULL, attempts INT NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL, published_at TIMESTAMPTZ);
